export type UUID = string;

export type TaskStatus = 'todo' | 'in-progress' | 'done';

export interface User {
  id: UUID;
  name: string;
  email: string;
}

export interface Project {
  id: UUID;
  name: string;
  description: string;
  memberIds: string[];
}

export interface Task {
  id: UUID;
  title: string;
  description: string;
  status: TaskStatus;
  assigneeId: string | null;
  projectId: string;
}

export interface Comment {
  id: UUID;
  taskId: string;
  authorId: string;
  body: string;
  createdAt: string; // ISO
}

export interface Notification {
  id: UUID;
  userId: string;
  message: string;
  read: boolean;
  createdAt: string;
}

type Callback = (payload: any) => void;

export class EventBus {
  private subscribers: Map<string, Set<Callback>> = new Map();

  publish(event: string, payload: any): void {
    const subs = this.subscribers.get(event);
    if (!subs) return;
    for (const cb of subs) {
      // deliver asynchronously to avoid blocking
      setImmediate(() => {
        try {
          cb(payload);
        } catch (err) {
          // swallow
          console.error('Event handler error for', event, err);
        }
      });
    }
  }

  subscribe(event: string, callback: Callback): void {
    const subs = this.subscribers.get(event) ?? new Set();
    subs.add(callback);
    this.subscribers.set(event, subs);
  }
}

import { User, UUID } from '../types';
import { randomUUID } from 'crypto';

export class UserService {
  private store: Map<UUID, User> = new Map();

  create(payload: { name: string; email: string }): User {
    const id = randomUUID();
    const user: User = { id, name: payload.name, email: payload.email };
    this.store.set(id, user);
    return user;
  }

  getById(id: UUID): User | null {
    return this.store.get(id) ?? null;
  }

  getAll(): User[] {
    return Array.from(this.store.values());
  }

  update(id: UUID, payload: { name?: string; email?: string }): User | null {
    const existing = this.store.get(id);
    if (!existing) return null;
    const updated: User = { ...existing, ...payload };
    this.store.set(id, updated);
    return updated;
  }

  delete(id: UUID): boolean {
    return this.store.delete(id);
  }
}

import { Project, UUID } from '../types';
import { randomUUID } from 'crypto';

export class ProjectService {
  private store: Map<UUID, Project> = new Map();

  create(payload: { name: string; description?: string; memberIds?: string[] }): Project {
    const id = randomUUID();
    const p: Project = { id, name: payload.name, description: payload.description ?? '', memberIds: payload.memberIds ?? [] };
    this.store.set(id, p);
    return p;
  }

  getById(id: UUID): Project | null {
    return this.store.get(id) ?? null;
  }

  getAll(): Project[] {
    return Array.from(this.store.values());
  }

  update(id: UUID, payload: { name?: string; description?: string }): Project | null {
    const existing = this.store.get(id);
    if (!existing) return null;
    const updated: Project = { ...existing, ...payload };
    this.store.set(id, updated);
    return updated;
  }

  delete(id: UUID): boolean {
    return this.store.delete(id);
  }

  addMember(projectId: UUID, userId: UUID): Project | null {
    const p = this.store.get(projectId);
    if (!p) return null;
    if (!p.memberIds.includes(userId)) p.memberIds.push(userId);
    return p;
  }

  removeMember(projectId: UUID, userId: UUID): Project | null {
    const p = this.store.get(projectId);
    if (!p) return null;
    p.memberIds = p.memberIds.filter(id => id !== userId);
    this.store.set(projectId, p);
    return p;
  }
}

import { Task, TaskStatus, UUID } from '../types';
import { randomUUID } from 'crypto';
import { EventBus } from '../event-bus';

export class TaskService {
  private store: Map<UUID, Task> = new Map();
  constructor(private bus: EventBus) {}

  create(payload: { title: string; description?: string; projectId: string; assigneeId?: string | null }): Task {
    const id = randomUUID();
    const task: Task = {
      id,
      title: payload.title,
      description: payload.description ?? '',
      status: 'todo',
      assigneeId: payload.assigneeId ?? null,
      projectId: payload.projectId,
    };
    this.store.set(id, task);
    if (task.assigneeId) {
      this.bus.publish('task.assigned', { taskId: task.id, taskTitle: task.title, assigneeId: task.assigneeId });
    }
    return task;
  }

  getById(id: UUID): Task | null {
    return this.store.get(id) ?? null;
  }

  getByProject(projectId: string): Task[] {
    return Array.from(this.store.values()).filter(t => t.projectId === projectId);
  }

  update(id: UUID, payload: { title?: string; description?: string }): Task | null {
    const t = this.store.get(id);
    if (!t) return null;
    const updated: Task = { ...t, ...payload };
    this.store.set(id, updated);
    return updated;
  }

  delete(id: UUID): boolean {
    return this.store.delete(id);
  }

  assign(id: UUID, assigneeId: string | null): Task | null {
    const t = this.store.get(id);
    if (!t) return null;
    t.assigneeId = assigneeId;
    this.store.set(id, t);
    this.bus.publish('task.assigned', { taskId: t.id, taskTitle: t.title, assigneeId });
    return t;
  }

  changeStatus(id: UUID, newStatus: TaskStatus): Task | { error: string } | null {
    const t = this.store.get(id);
    if (!t) return null;
    const order: TaskStatus[] = ['todo', 'in-progress', 'done'];
    const oldIdx = order.indexOf(t.status);
    const newIdx = order.indexOf(newStatus);
    if (newIdx === -1) return { error: 'invalid status' };
    if (newIdx < oldIdx) return { error: 'status transition must be forward only' };
    if (newIdx === oldIdx) return t;
    const oldStatus = t.status;
    t.status = newStatus;
    this.store.set(id, t);
    this.bus.publish('task.statusChanged', { taskId: t.id, taskTitle: t.title, assigneeId: t.assigneeId, oldStatus, newStatus });
    return t;
  }
}

import { Comment, UUID } from '../types';
import { randomUUID } from 'crypto';
import { EventBus } from '../event-bus';

export class CommentService {
  private store: Map<UUID, Comment> = new Map();
  constructor(private bus: EventBus) {}

  create(payload: { taskId: string; authorId: string; body: string; authorName?: string; taskTitle?: string }): Comment {
    const id = randomUUID();
    const c: Comment = { id, taskId: payload.taskId, authorId: payload.authorId, body: payload.body, createdAt: new Date().toISOString() };
    this.store.set(id, c);
    // publish event with authorName and taskTitle if provided
    this.bus.publish('comment.added', { commentId: id, taskId: payload.taskId, taskTitle: payload.taskTitle ?? '', authorId: payload.authorId, authorName: payload.authorName ?? '' });
    return c;
  }

  getById(id: UUID): Comment | null {
    return this.store.get(id) ?? null;
  }

  getByTask(taskId: string): Comment[] {
    return Array.from(this.store.values()).filter(c => c.taskId === taskId);
  }

  delete(id: UUID): boolean {
    return this.store.delete(id);
  }
}

import { Notification, UUID } from '../types';
import { randomUUID } from 'crypto';
import { EventBus } from '../event-bus';

export class NotificationService {
  private store: Map<UUID, Notification> = new Map();

  constructor(private bus: EventBus) {
    // subscribe to events
    bus.subscribe('task.assigned', payload => this.onTaskAssigned(payload));
    bus.subscribe('task.statusChanged', payload => this.onTaskStatusChanged(payload));
    bus.subscribe('comment.added', payload => this.onCommentAdded(payload));
  }

  private pushNotification(userId: string | null | undefined, message: string) {
    if (!userId) return;
    const id = randomUUID();
    const n: Notification = { id, userId, message, read: false, createdAt: new Date().toISOString() };
    this.store.set(id, n);
  }

  private onTaskAssigned(payload: any) {
    const { taskId, taskTitle, assigneeId } = payload;
    this.pushNotification(assigneeId, `Task assigned: ${taskTitle} (${taskId})`);
  }

  private onTaskStatusChanged(payload: any) {
    const { taskId, taskTitle, assigneeId, oldStatus, newStatus } = payload;
    this.pushNotification(assigneeId, `Task status changed: ${taskTitle} (${taskId}) ${oldStatus} -> ${newStatus}`);
  }

  private onCommentAdded(payload: any) {
    const { taskId, taskTitle, authorId, authorName } = payload;
    // Ideally we'd look up the task to find the assignee, but services cannot read other stores.
    // Therefore, comment.added event should include task assignee if needed. But per constraints, we'll include in payload when comment created if available.
    const { assigneeId } = payload as any;
    if (assigneeId) this.pushNotification(assigneeId, `New comment on ${taskTitle || taskId} by ${authorName || authorId}`);
  }

  getByUser(userId: string): Notification[] {
    return Array.from(this.store.values()).filter(n => n.userId === userId);
  }

  markAsRead(id: UUID): Notification | null {
    const n = this.store.get(id);
    if (!n) return null;
    n.read = true;
    this.store.set(id, n);
    return n;
  }
}

import { createServer, IncomingMessage, ServerResponse } from 'http';
import { parse as parseUrl, UrlWithParsedQuery } from 'url';

import { EventBus } from './event-bus';
import { UserService } from './services/user-service';
import { ProjectService } from './services/project-service';
import { TaskService } from './services/task-service';
import { CommentService } from './services/comment-service';
import { NotificationService } from './services/notification-service';

export class APIRouter {
  private bus = new EventBus();
  private users = new UserService();
  private projects = new ProjectService();
  private tasks = new TaskService(this.bus);
  private comments = new CommentService(this.bus);
  private notifs = new NotificationService(this.bus);

  server = createServer((req, res) => this.handle(req, res));

  listen(port: number, cb?: () => void) {
    this.server.listen(port, cb);
  }

  private async handle(req: IncomingMessage, res: ServerResponse) {
    const parsed = parseUrl(req.url || '', true) as UrlWithParsedQuery;
    const method = req.method || 'GET';
    const path = parsed.pathname || '/';

    // simple body parsing
    const body = await new Promise<any>(resolve => {
      let s = '';
      req.on('data', chunk => s += chunk);
      req.on('end', () => {
        try { resolve(s ? JSON.parse(s) : null); } catch { resolve(null); }
      });
    });

    // route matching
    try {
      // Users
      if (method === 'GET' && path === '/users') return this.ok(res, this.users.getAll());
      if (method === 'POST' && path === '/users') {
        const u = this.users.create(body || {});
        return this.ok(res, u, 201);
      }
      if (path?.startsWith('/users/')) {
        const id = path.split('/')[2];
        if (method === 'GET') return this.ok(res, this.users.getById(id));
        if (method === 'PUT') return this.ok(res, this.users.update(id, body || {}));
        if (method === 'DELETE') return this.ok(res, { deleted: this.users.delete(id) });
      }

      // Projects
      if (method === 'GET' && path === '/projects') return this.ok(res, this.projects.getAll());
      if (method === 'POST' && path === '/projects') return this.ok(res, this.projects.create(body || {}), 201);
      if (path?.startsWith('/projects/')) {
        const parts = path.split('/');
        const id = parts[2];
        if (parts.length === 3) {
          if (method === 'GET') return this.ok(res, this.projects.getById(id));
          if (method === 'PUT') return this.ok(res, this.projects.update(id, body || {}));
          if (method === 'DELETE') return this.ok(res, { deleted: this.projects.delete(id) });
        }
        if (parts.length === 4 && parts[3] === 'members') {
          if (method === 'POST') return this.ok(res, this.projects.addMember(id, body.userId));
          if (method === 'DELETE') return this.ok(res, this.projects.removeMember(id, body.userId));
        }
      }

      // Tasks
      if (method === 'GET' && path === '/tasks') {
        const projectId = parsed.query.projectId as string | undefined;
        if (projectId) return this.ok(res, this.tasks.getByProject(projectId));
        return this.ok(res, []);
      }
      if (method === 'POST' && path === '/tasks') {
        const t = this.tasks.create(body || {});
        return this.ok(res, t, 201);
      }
      if (path?.startsWith('/tasks/')) {
        const parts = path.split('/');
        const id = parts[2];
        if (parts.length === 3) {
          if (method === 'GET') return this.ok(res, this.tasks.getById(id));
          if (method === 'PUT') return this.ok(res, this.tasks.update(id, body || {}));
          if (method === 'DELETE') return this.ok(res, { deleted: this.tasks.delete(id) });
        }
        if (parts.length === 4 && parts[3] === 'status' && method === 'PUT') {
          const result = this.tasks.changeStatus(id, body.newStatus);
          return this.ok(res, result);
        }
        if (parts.length === 4 && parts[3] === 'assign' && method === 'PUT') {
          const result = this.tasks.assign(id, body.assigneeId ?? null);
          return this.ok(res, result);
        }
      }

      // Comments
      if (method === 'GET' && path === '/comments') {
        const taskId = parsed.query.taskId as string | undefined;
        if (taskId) return this.ok(res, this.comments.getByTask(taskId));
        return this.ok(res, []);
      }
      if (method === 'POST' && path === '/comments') {
        // We may want to include taskTitle and authorName for notification service
        const comment = this.comments.create(body || {});
        return this.ok(res, comment, 201);
      }
      if (path?.startsWith('/comments/')) {
        const id = path.split('/')[2];
        if (method === 'GET') return this.ok(res, this.comments.getById(id));
        if (method === 'DELETE') return this.ok(res, { deleted: this.comments.delete(id) });
      }

      // Notifications
      if (method === 'GET' && path === '/notifications') {
        const userId = parsed.query.userId as string | undefined;
        if (!userId) return this.badRequest(res, 'userId required');
        return this.ok(res, this.notifs.getByUser(userId));
      }
      if (path?.startsWith('/notifications/')) {
        const parts = path.split('/');
        const id = parts[2];
        if (parts.length === 4 && parts[3] === 'read' && method === 'PUT') {
          return this.ok(res, this.notifs.markAsRead(id));
        }
      }

      this.notFound(res);
    } catch (err) {
      console.error(err);
      this.serverError(res);
    }
  }

  private ok(res: ServerResponse, data: any, status = 200) {
    res.writeHead(status, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify(data));
  }
  private badRequest(res: ServerResponse, msg: string) {
    res.writeHead(400, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: msg }));
  }
  private notFound(res: ServerResponse) {
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'not found' }));
  }
  private serverError(res: ServerResponse) {
    res.writeHead(500, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'server error' }));
  }
}

import { APIRouter } from './router';

const router = new APIRouter();
const port = Number(process.env.PORT ?? 3000);
router.listen(port, () => console.log(`Server listening on http://localhost:${port}`));

// Graceful shutdown
process.on('SIGINT', () => process.exit(0));
process.on('SIGTERM', () => process.exit(0));

import { APIRouter } from './router';
import http from 'http';

function req(options: { method?: string; path: string; body?: any }) {
  const method = options.method ?? 'GET';
  const bodyStr = options.body ? JSON.stringify(options.body) : undefined;
  return new Promise<any>((resolve, reject) => {
    const req = http.request({ hostname: 'localhost', port: 3000, path: options.path, method, headers: { 'Content-Type': 'application/json' } }, res => {
      let s = '';
      res.on('data', c => s += c);
      res.on('end', () => {
        try { resolve(s ? JSON.parse(s) : null); } catch (e) { resolve(s); }
      });
    });
    req.on('error', reject);
    if (bodyStr) req.write(bodyStr);
    req.end();
  });
}

async function main() {
  const router = new APIRouter();
  router.listen(3000);
  await new Promise(r => setTimeout(r, 50));
  console.log('Demo server started on port 3000');

  // create users
  const alice = await req({ method: 'POST', path: '/users', body: { name: 'Alice', email: 'alice@example.com' } });
  const bob = await req({ method: 'POST', path: '/users', body: { name: 'Bob', email: 'bob@example.com' } });
  console.log('Users:', alice, bob);

  // create project
  const project = await req({ method: 'POST', path: '/projects', body: { name: 'Project X', description: 'Top secret' } });
  console.log('Project:', project);

  // add members
  await req({ method: 'POST', path: `/projects/${project.id}/members`, body: { userId: alice.id } });
  await req({ method: 'POST', path: `/projects/${project.id}/members`, body: { userId: bob.id } });
  const projAfter = await req({ method: 'GET', path: `/projects/${project.id}` });
  console.log('Project after members:', projAfter);

  // create task assigned to Alice
  const task = await req({ method: 'POST', path: '/tasks', body: { title: 'Setup repo', description: 'Init git', projectId: project.id, assigneeId: alice.id } });
  console.log('Task created:', task);

  // change status to in-progress
  await req({ method: 'PUT', path: `/tasks/${task.id}/status`, body: { newStatus: 'in-progress' } });
  // change status to done
  await req({ method: 'PUT', path: `/tasks/${task.id}/status`, body: { newStatus: 'done' } });

  // add comment by Bob
  await req({ method: 'POST', path: '/comments', body: { taskId: task.id, authorId: bob.id, body: 'Please add README', authorName: 'Bob', taskTitle: task.title, assigneeId: task.assigneeId } });

  // fetch notifications for Alice
  const notes = await req({ method: 'GET', path: `/notifications?userId=${alice.id}` });
  console.log('Notifications for Alice:', notes);

  // mark first as read
  if (notes && notes.length) {
    await req({ method: 'PUT', path: `/notifications/${notes[0].id}/read` });
  }

  const notesAfter = await req({ method: 'GET', path: `/notifications?userId=${alice.id}` });
  console.log('Notifications after marking read:', notesAfter);

  console.log('Demo complete');
  process.exit(0);
}

if (require.main === module) main();

